export const initialPolicy = "<h2>TopMCQBD রিফান্ড ও গোপনীয়তা নীতিমালা</h2><p>TopMCQBD তে আপনাকে স্বাগতম। আমাদের প্ল্যাটফর্ম ব্যবহার করার মাধ্যমে আপনি নিম্নলিখিত শর্তাবলি মেনে নিচ্ছেন।</p><h3>১. অ্যাকাউন্ট ও নিরাপত্তা</h3><p>আপনার অ্যাকাউন্ট আইডি ও পাসওয়ার্ডের নিরাপত্তা রক্ষা করা সম্পূর্ণ আপনার দায়িত্ব। সঠিক তথ্য দিয়ে অ্যাকাউন্ট খোলার জন্য অনুরোধ করা হচ্ছে।</p><h3>২. সাবস্ক্রিপশন ও রিফান্ড নীতি</h3><p>যেকোনো প্রিমিয়াম প্যাকেজ ক্রয়ের পর পেমেন্ট ভেরিফিকেশনের মাধ্যমে অ্যাক্সেস চালু করা হয়। কোনো প্রকার ভুল বা অসদুপায় অবলম্বন করলে অ্যাকাউন্ট সাময়িকভাবে স্থগিত হতে পারে।</p><h3>৩. গোপনীয়তা নীতি</h3><p>আপনার ব্যক্তিগত তথ্য (নাম, ইমেইল, ফোন নম্বর) তৃতীয় কোনো পক্ষের কাছে শেয়ার করা হয় না। সকল তথ্য নিরাপদ ডাটাবেজে সংরক্ষিত থাকে।</p>";
